/**
 * Authored Blender props.
 *
 * The GLBs in `src/assets/models` are generated by
 * `scripts/models/build_models.py`. They are loaded during boot and handed to
 * the world builders, which still keep their procedural versions as a fallback
 * so a missing or corrupt asset never blocks the game.
 */

import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import roverUrl from '../assets/models/rover.glb?url';
import landerUrl from '../assets/models/lander.glb?url';
import astronautUrl from '../assets/models/astronaut.glb?url';

const SOURCES = {
  rover: roverUrl,
  lander: landerUrl,
  astronaut: astronautUrl,
};

function prepare(root) {
  root.traverse((object) => {
    if (!object.isMesh) return;
    object.castShadow = true;
    object.receiveShadow = true;
    const materials = Array.isArray(object.material) ? object.material : [object.material];
    for (const material of materials) {
      if (!material) continue;
      material.flatShading = true;
      // Glow parts are authored with an emissive material in Blender. Keep
      // them outside tone mapping so the small lights still read at distance.
      if (material.name?.startsWith('Glow')) {
        material.toneMapped = false;
        material.emissiveIntensity = Math.max(material.emissiveIntensity ?? 1, 2);
      }
      material.needsUpdate = true;
    }
  });
}

export async function loadWorldModels(onProgress) {
  const loader = new GLTFLoader();
  const keys = Object.keys(SOURCES);
  const models = {};
  let done = 0;

  await Promise.all(
    keys.map(async (key) => {
      try {
        const gltf = await loader.loadAsync(SOURCES[key]);
        prepare(gltf.scene);
        models[key] = gltf.scene;
      } catch (error) {
        console.warn(`[models] could not load "${key}", using procedural fallback`, error);
        models[key] = null;
      } finally {
        done += 1;
        onProgress?.(done, keys.length);
      }
    })
  );

  return models;
}
